import React from 'react';

interface Verb {
	verb: string;
	translation: string;
	preposition: string[];
	case: 'dat' | 'akk';
	examples?: string[];
}

interface VerbMitPropTheoryModalProps {
	open: boolean;
	onClose: () => void;
	verbs: Verb[];
}

export function VerbMitPrapTheoryModal({
	open,
	onClose,
	verbs,
}: VerbMitPropTheoryModalProps) {
	if (!open) return null;

	return (
		<div className="fixed inset-0 z-50">
			<div className="absolute inset-0 bg-black/50" onClick={onClose}></div>
			<div className="absolute inset-x-2 top-4 bottom-4 max-w-2xl mx-auto bg-white rounded-2xl shadow-xl p-4 flex flex-col">
				<div className="flex items-center justify-between mb-3">
					<div className="font-semibold text-lg">Глаголы c предлогами</div>
					<button onClick={onClose} className="text-xs text-gray-500">
						Закрыть
					</button>
				</div>

				<div className="overflow-y-auto flex-1 pr-1">
					<table className="w-full text-sm border-collapse mb-3">
						<thead>
							<tr className="border-b text-left text-gray-600 text-xs">
								<th className="py-1 w-8">№</th>
								<th className="py-1">Инфинитив</th>
								<th className="py-1">Предлог</th>
								<th className="py-1">Падеж</th>
							</tr>
						</thead>
						<tbody>
							{verbs.map((v, i) => (
								<React.Fragment key={i}>
									<tr className="align-top">
										<td className="py-1">{i + 1}</td>
										<td className="py-1">
											{v.verb}{' '}
											<span className="text-gray-400">({v.translation})</span>
										</td>
										<td className="py-1 font-semibold">
											{v.preposition.join(', ')}
										</td>
										<td className="py-1 ">{v.case}</td>
									</tr>
									{v.examples && v.examples.length > 0 && (
										<tr className="border-b last:border-0">
											<td></td>
											<td colSpan={3} className="py-1 italic text-gray-700">
												{v.examples[0]}
											</td>
										</tr>
									)}
								</React.Fragment>
							))}
						</tbody>
					</table>
				</div>
			</div>
		</div>
	);
}
